import '../../../core/constants/default_categories.dart';

/// Represents a category suggestion generated by matching keywords.
class CategorySuggestion {
  /// The matched category unique identifier.
  final String categoryId;

  /// The human-readable name of the category.
  final String categoryName;

  /// The specific keyword that triggered this suggestion.
  final String matchedKeyword;

  const CategorySuggestion({
    required this.categoryId,
    required this.categoryName,
    required this.matchedKeyword,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CategorySuggestion &&
          runtimeType == other.runtimeType &&
          categoryId == other.categoryId &&
          categoryName == other.categoryName &&
          matchedKeyword == other.matchedKeyword;

  @override
  int get hashCode => Object.hash(categoryId, categoryName, matchedKeyword);

  @override
  String toString() =>
      'CategorySuggestion($categoryName, keyword: "$matchedKeyword")';
}

/// Keyword-based suggestion engine for categorizing merchants and transaction notes.
