      'timezone',
    ],
  };

  /// Analyzes [text] (merchant name, transaction note, or notification body)
  /// and returns the most suitable [CategorySuggestion], or `null` if no keywords match.
  static CategorySuggestion? suggest(String? text) {
    if (text == null || text.trim().isEmpty) return null;
    final clean = text.toLowerCase();

    for (final entry in _keywordsByCategory.entries) {
      for (final keyword in entry.value) {
        if (_matches(clean, keyword)) {
          final categoryId = entry.key;
          final categoryName = _nameFor(categoryId);
          return CategorySuggestion(
            categoryId: categoryId,
            categoryName: categoryName,
            matchedKeyword: keyword,
          );
        }
      }
    }

    return null;
  }

  /// Suggests a category ID, falling back to [DefaultCategories.otherId] if no match.
  static String suggestCategoryId(String? text) {
    return suggest(text)?.categoryId ?? DefaultCategories.otherId;
  }

  /// Suggests a human-readable category name, falling back to [DefaultCategories.otherName] if no match.
  static String suggestCategoryName(String? text) {
    return suggest(text)?.categoryName ?? DefaultCategories.otherName;
  }

  static bool _matches(String text, String keyword) {
    // For short 2-3 letter words (e.g., 'rs', 'bp', 'tj', 'kai', 'mrt'), require full-word boundary match.
    if (keyword.length <= 3) {
      final pattern = RegExp(
        r'(?:\b|_)' + RegExp.escape(keyword) + r'(?:\b|_)',
        caseSensitive: false,
      );
      return pattern.hasMatch(text);
    }

    return text.contains(keyword);
  }

  static String _nameFor(String id) {
    return switch (id) {
      DefaultCategories.foodId => DefaultCategories.foodName,
      DefaultCategories.transportId => DefaultCategories.transportName,
      DefaultCategories.billsId => DefaultCategories.billsName,
      DefaultCategories.shoppingId => DefaultCategories.shoppingName,
      DefaultCategories.healthId => DefaultCategories.healthName,
      DefaultCategories.entertainmentId => DefaultCategories.entertainmentName,
      _ => DefaultCategories.otherName,
    };
  }
}
